/**
 * Vendored Office SmartArt quartet parts (layout / colors / quickStyle) for the
 * four insert presets, plus the ids the generated data1.xml doc point carries
 * (loTypeId/qsTypeId/csTypeId must match the vendored parts' uniqueIds).
 *
 * Provenance: Office built-in layout definitions extracted from the MIT-licensed
 * test fixtures of dotnet/Open-XML-SDK (Office "O12" templates; extraction catalog:
 * github.com/SteveGJones/jack-tar-deckhand plugins/jack-tar-msft-smartart/data).
 * Word embeds a copy of the chosen built-in layout per saved diagram, so shipping
 * these verbatim matches Word's own output. UniqueIds keep Office's `,#N` variant
 * suffixes exactly as authored.
 */
import type { NewDiagramPreset } from './types'

export interface SmartArtPresetParts {
  /** dgm:layoutDef part body (word/diagrams/layoutN.xml) */
  layoutXml: string
  /** dgm:colorsDef part body (word/diagrams/colorsN.xml) */
  colorsXml: string
  /** dgm:styleDef part body (word/diagrams/quickStyleN.xml) */
  quickStyleXml: string
  /** vendored layout's uniqueId (dgm:layoutDef/@uniqueId, data1 doc point loTypeId) */
  loTypeId: string
  /** layout gallery category (data1 doc point loCatId) */
  loCatId: string
  /** vendored quickStyle's uniqueId (data1 doc point qsTypeId) */
  qsTypeId: string
  /** quickStyle gallery category (data1 doc point qsCatId) */
  qsCatId: string
  /** vendored colors' uniqueId (data1 doc point csTypeId) */
  csTypeId: string
  /** colors gallery category (data1 doc point csCatId) */
  csCatId: string
}

